import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function SearchBar() {
  const [query, setQuery] = useState('');
  const navigate = useNavigate();

  const handleSearch = (e) => {
    e.preventDefault();

    const trimmed = query.trim();
    if (trimmed) {
      // Navigate to the search result page with the query in URL
      navigate(`/search-results?place=${encodeURIComponent(trimmed)}`);
    }
  };

  return (
    <div style={{ width: '100%', display: 'flex', justifyContent: 'center', marginTop: '2rem' }}>
      <form onSubmit={handleSearch} style={{ display: 'flex', width: '50%' }}>
        <input
          type="text"
          placeholder="Search locations..."
          style={{ flex: 1, padding: '10px', border: '1px solid gray', borderRadius: '4px 0 0 4px' }}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <button
          type="submit"
          style={{
            padding: '10px 16px',
            backgroundColor: '#2563eb',
            color: 'white',
            border: 'none',
            borderRadius: '0 4px 4px 0',
            cursor: 'pointer',
          }}
        >
          Search
        </button>
      </form>
    </div>
  );
}

export default SearchBar;
